from storage import load_all, save

def test_upgrade_v1_to_v2():
    v1 = {"id": 1, "name": "Project A", "remote": "yes"}
    v2 = upgrade(v1)
    assert v2 == {"id": 1, "title": "Project A", "work_mode": "remote", "version": 2}
    assert v1 == {"id": 1, "name": "Project A", "remote": "yes"}  # Never modify input

    v1_no = {"id": 2, "name": "Project B", "remote": "no"}
    v2_no = upgrade(v1_no)
    assert v2_no == {"id": 2, "title": "Project B", "work_mode": "office", "version": 2}
    assert v1_no == {"id": 2, "name": "Project B", "remote": "no"}

    v1_missing = {"id": 3, "name": "Project C"}
    v2_missing = upgrade(v1_missing)
    assert v2_missing == {"id": 3, "title": "Project C", "work_mode": "unknown", "version": 2}
    assert v1_missing == {"id": 3, "name": "Project C"}

    v1_invalid = {"id": 4, "name": "Project D", "remote": "maybe"}
    try:
        upgrade(v1_invalid)
    except ValueError:
        pass
    else:
        assert False, "Should have raised ValueError for 'maybe'"

def test_upgrade_idempotent():
    v2 = {"id": 1, "title": "Project A", "work_mode": "remote", "version": 2}
    v2_copy = upgrade(v2)
    assert v2_copy == v2
    assert v2_copy is not v2

def test_storage_load_all():
    rows = [
